/* generated by make_mapdata.py - id maps for on-band map
 * composition. Normal tiles and autotile blocks are looked up
 * from bsvm_mapdata.bin; flags carry TABLE(bit7)/OVER(bit4). */
#ifndef BSVM_MAPDEF_H
#define BSVM_MAPDEF_H

typedef struct { uint16_t id; uint16_t idx; uint16_t flags; } bsmd_ent;

/* normal tile ids -> cell index in mapdata */
static const bsmd_ent bsmd_normal[] = {
    { 0x0005, 0, 0x0000 },
    { 0x0046, 1, 0x0000 },
    { 0x0047, 2, 0x0000 },
    { 0x004E, 3, 0x0000 },
    { 0x004F, 4, 0x0000 },
    { 0x0068, 5, 0x0000 },
    { 0x013F, 6, 0x0000 },
    { 0x01E0, 7, 0x0010 },
    { 0x01E1, 8, 0x0010 },
    { 0x01E2, 9, 0x0000 },
    { 0x01E8, 10, 0x0000 },
    { 0x01E9, 11, 0x0000 },
    { 0x01F0, 12, 0x0000 },
    { 0x01F1, 13, 0x0000 },
    { 0x01F8, 14, 0x0000 },
    { 0x01F9, 15, 0x0000 },
    { 0x0600, 16, 0x0000 },
    { 0x0641, 17, 0x0000 },
};
#define BSMD_NORMAL_N 18
#define BSMD_PLAYER_CELL 18  /* soul flame standing frame (appended after normal tiles) */
#define BSMD_PLAYER_TX 12
#define BSMD_PLAYER_TY 18

/* autotile (base, at) -> block index, block height in tiles,
 * fl bit7 = table tile (A2 6-quad legs) */
typedef struct { uint16_t base; uint16_t at; uint16_t blk; uint16_t h; uint16_t fl; } bsmd_at_ent;
static const bsmd_at_ent bsmd_at_list[] = {
    { 0x0B00, 7, 0, 3, 0x0081 },
    { 0x0B00, 19, 1, 3, 0x0000 },
    { 0x1700, 33, 2, 3, 0x0001 },
    { 0x1700, 41, 3, 2, 0x0001 },
};
#define BSMD_AT_N 4

#define BSMD_TM_LAYERS 4
#define BSMD_TM_X 28
#define BSMD_TM_Y 24
#define BSMD_BANDS 12  /* tile rows / 2, rounded up */

#endif
